import { useCallback, useEffect, useState } from "react";
import clsx from "clsx";
import { Activity, Play, ScrollText, Square } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import {
  BootstrapRecommended,
  GetServiceLogs,
  IsRecommendedReady,
  ListServices,
  StartService,
  StartVisible,
  StopService,
  StopVisible,
} from "../../wailsjs/go/controllers/Services";
// @ts-ignore wailsjs bindings are generated by wails build
import { GetSystemMetrics } from "../../wailsjs/go/controllers/System";
// @ts-ignore wailsjs bindings are generated by wails build
import { EventsOn } from "../../wailsjs/runtime";
import { useDialogs } from "../components/dialogs/DialogProvider";
import { useT } from "../lib/i18n";

export type ServiceCard = {
  name: string;
  labelKey: string;
  running: boolean;
  installed: boolean;
  version?: string;
  hasLogs: boolean;
};

type Metrics = {
  cpu: number;
  ramUsed: number;
  ramTotal: number;
  diskFree: number;
  diskTotal: number;
};

export default function Dashboard() {
  const t = useT();
  const dialogs = useDialogs();
  const [services, setServices] = useState<ServiceCard[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [starterReady, setStarterReady] = useState(true);
  const [logViewer, setLogViewer] = useState<string | null>(null);

  const refresh = useCallback(() => {
    ListServices().then((list: ServiceCard[]) => setServices(list ?? [])).catch(() => { /* pre-startup */ });
  }, []);

  useEffect(() => {
    refresh();
    GetSystemMetrics().then((m: Metrics) => setMetrics(m)).catch(() => { /* pre-startup */ });
    IsRecommendedReady().then((ready: boolean) => setStarterReady(ready)).catch(() => setStarterReady(true));
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("service:status", () => refresh());
  }, [refresh]);

  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("sys:metrics", (sample: Metrics) => setMetrics(sample));
  }, []);

  useEffect(() => {
    // @ts-ignore EventsOn returns a cancel function
    return EventsOn("service:error", async (payload: { name: string; message: string; redist?: string }) => {
      if (payload?.redist) {
        await dialogs.alert({ title: t("vc.title"), message: t("vc.body") });
        return;
      }
      await dialogs.alert({
        title: t("services.failed", { name: t(`services.names.${payload.name}`) }),
        message: payload.message,
      });
    });
  }, [dialogs, t]);

  const act = async (id: string, action: "start" | "stop") => {
    setBusy(id + action);
    try {
      if (action === "start") await StartService(id);
      else await StopService(id);
    } catch (error) {
      await dialogs.alert({ title: t("services.names." + id), message: String(error) });
    } finally {
      setBusy(null);
      refresh();
    }
  };

  const anyRunning = services.some((s) => s.running);

  return (
    <div className="space-y-4">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h1 className="text-lg font-semibold text-white/95">{t("dashboard.title")}</h1>
          <p className="text-xs text-white/50">{t("dashboard.subtitle")}</p>
        </div>
        <div className="flex gap-2">
          <button
            type="button"
            disabled={!anyRunning}
            onClick={async () => {
              await StopVisible();
              refresh();
            }}
            className="flex items-center gap-1.5 rounded-md border border-white/10 bg-white/5 px-3 py-1.5 text-xs text-white/80 hover:bg-white/10 disabled:opacity-40"
          >
            <Square className="h-3.5 w-3.5" /> {t("services.stopAll")}
          </button>
          <button
            type="button"
            onClick={async () => {
              await StartVisible();
              refresh();
            }}
            className="flex items-center gap-1.5 rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-white hover:bg-accent/85"
          >
            <Play className="h-3.5 w-3.5" /> {t("services.startAll")}
          </button>
        </div>
      </header>

      {!starterReady && (
        <section className="glass flex flex-wrap items-center justify-between gap-3 p-4">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold text-white/90">{t("dashboard.bootstrap.title")}</h2>
            <p className="mt-1 max-w-[560px] text-xs leading-relaxed text-white/55">{t("dashboard.bootstrap.body")}</p>
          </div>
          <button
            type="button"
            onClick={async () => {
              setStarterReady(true); // the card steps aside while it works
              await BootstrapRecommended();
            }}
            className="rounded-md bg-accent px-4 py-2 text-xs font-medium text-white hover:bg-accent/85"
          >
            {t("dashboard.bootstrap.button")}
          </button>
        </section>
      )}

      {services.length === 0 ? (
        <section className="glass p-8 text-center">
          <p className="text-sm font-medium text-white/80">{t("dashboard.noServices.title")}</p>
          <p className="mt-1 text-xs text-white/50">{t("dashboard.noServices.body")}</p>
        </section>
      ) : (
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {services.map((service) => (
            <article key={service.name} className="glass flex flex-col gap-3 p-4">
              <div className="flex items-start justify-between gap-2">
                <div className="min-w-0">
                  <h3 className="truncate text-sm font-semibold text-white/90">{t(service.labelKey)}</h3>
                  <p className="text-[11px] text-white/40">{service.version || service.name}</p>
                </div>
                <span
                  title={service.running ? t("services.state.running") : t("services.state.stopped")}
                  className={clsx(
                    "mt-1 h-2.5 w-2.5 shrink-0 rounded-full",
                    service.running ? "bg-emerald-400 shadow-[0_0_8px_rgba(52,211,153,0.8)]" : "bg-white/20",
                  )}
                />
              </div>
              <div className="flex items-center gap-2">
                {service.installed ? (
                  <button
                    type="button"
                    disabled={busy !== null}
                    onClick={() => act(service.name, service.running ? "stop" : "start")}
                    className={clsx(
                      "flex flex-1 items-center justify-center gap-1.5 rounded-md px-2 py-1.5 text-xs font-medium disabled:opacity-40",
                      service.running
                        ? "border border-white/10 bg-white/5 text-white/80 hover:bg-white/10"
                        : "bg-accent text-white hover:bg-accent/85",
                    )}
                  >
                    {service.running ? <Square className="h-3 w-3" /> : <Play className="h-3 w-3" />}
                    {service.running ? t("services.action.stop") : t("services.action.start")}
                  </button>
                ) : (
                  <span className="flex-1 rounded-md border border-white/10 px-2 py-1.5 text-center text-[11px] text-white/40">
                    {t("services.state.notInstalled")}
                  </span>
                )}
                <button
                  type="button"
                  onClick={() => setLogViewer(service.name)}
                  title={t("services.action.logs")}
                  className="rounded-md border border-white/10 p-1.5 text-white/60 hover:bg-white/10 hover:text-white"
                >
                  <ScrollText className="h-3.5 w-3.5" />
                </button>
              </div>
            </article>
          ))}
        </div>
      )}

      {metrics && <MetricsPanel sample={metrics} />}
      {logViewer && <LogsModal name={logViewer} onClose={() => setLogViewer(null)} />}
    </div>
  );
}

function MetricsPanel({ sample }: { sample: Metrics }) {
  const t = useT();
  const ramPct = sample.ramTotal > 0 ? Math.round((sample.ramUsed / sample.ramTotal) * 100) : 0;
  const diskPct = sample.diskTotal > 0 ? Math.round(((sample.diskTotal - sample.diskFree) / sample.diskTotal) * 100) : 0;
  return (
    <section className="glass p-4">
      <h2 className="mb-3 flex items-center gap-2 text-sm font-semibold text-white/90">
        <Activity className="h-4 w-4 text-accent2" /> {t("dashboard.metrics.title")}
      </h2>
      <div className="grid grid-cols-3 gap-3">
        <Bar label={t("dashboard.metrics.cpu")} percent={sample.cpu} detail={`${sample.cpu}%`} />
        <Bar label={t("dashboard.metrics.ram")} percent={ramPct} detail={`${ramPct}%`} />
        <Bar label={t("dashboard.metrics.disk")} percent={diskPct} detail={`${diskPct}%`} />
      </div>
    </section>
  );
}

function Bar({ label, percent, detail }: { label: string; percent: number; detail: string }) {
  return (
    <div>
      <div className="mb-1 flex items-baseline justify-between text-[11px]">
        <span className="text-white/55">{label}</span>
        <span className="text-white/75">{detail}</span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-white/10">
        <div
          className="h-full rounded-full bg-gradient-to-r from-accent to-accent2 transition-[width] duration-500"
          style={{ width: `${Math.min(100, Math.max(0, percent))}%` }}
        />
      </div>
    </div>
  );
}

function LogsModal({ name, onClose }: { name: string; onClose: () => void }) {
  const t = useT();
  const [lines, setLines] = useState<string[]>([]);

  useEffect(() => {
    let alive = true;
    const pull = () => {
      GetServiceLogs(name).then((out: string[]) => {
        if (alive) setLines(out ?? []);
      }).catch(() => { /* pre-startup */ });
    };
    pull();
    const timer = window.setInterval(pull, 1200);
    return () => {
      alive = false;
      window.clearInterval(timer);
    };
  }, [name]);

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div
        role="dialog"
        aria-modal="true"
        onClick={(event) => event.stopPropagation()}
        className="modal-card flex h-[70vh] w-[720px] max-w-[92vw] flex-col p-4"
      >
        <h2 className="mb-2 text-sm font-semibold text-white/90">
          {t("logs.title", { name: t(`services.names.${name}`) })}
        </h2>
        <pre className="flex-1 overflow-auto whitespace-pre-wrap rounded bg-black/40 p-3 font-mono text-[11px] leading-relaxed text-white/80">
          {lines.length > 0 ? lines.join("\n") : t("logs.empty")}
        </pre>
        <footer className="mt-3 flex justify-end">
          <button
            type="button"
            onClick={onClose}
            className="rounded-md border border-white/10 px-3 py-1.5 text-xs text-white/75 hover:bg-white/10"
          >
            {t("logs.close")}
          </button>
        </footer>
      </div>
    </div>
  );
}
